def get_convex_hull(points):
    """Get convex hull of 2D points"""
    if not points:
        return set()

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

